$sql = @'
             CREATE TABLE #DbaClientXDemo
             (
                 Id int NOT NULL,
                 Name nvarchar(50) NOT NULL
             );
            
             INSERT INTO #DbaClientXDemo (Id, Name)
             VALUES (1, N'Alpha'), (2, N'Beta');
             '@
            
             Invoke-DbaXNonQuery -Server 'localhost' -Database 'master' -TrustServerCertificate -Query $sql

$reader = Invoke-DbaXQuery -Server 'sql01' -Database 'app' -Query 'SELECT * FROM dbo.Users' -AsDataReader
             try {
                 Export-OfficeCsv -InputObject $reader -Path .\Users.csv
             } finally {
                 $reader.Dispose()
             }
